<!doctype html>
<html lang="en" data-community-demo="0"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Community contributions | WROC-LOVE</title><link rel="icon" href="https://wroc-love.com/assets/logo.png"><link rel="stylesheet" href="./community.css"><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" integrity="sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=" crossorigin=""><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" integrity="sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=" crossorigin="" defer></script><script src="./community-copy.js" defer></script><script src="./community-app.js" defer></script></head><body><header class="community-header"><a id="community-home" href="/" aria-label="WROC-LOVE"><img src="https://wroc-love.com/assets/logo.png" alt="WROC-LOVE" width="58" height="58"></a><nav id="languages" aria-label="Language"></nav><a id="owner-link" href="?action=admin" hidden></a></header><main id="community-main"><section class="community-hero"><p class="eyebrow" data-copy="eyebrow"></p><h1 data-copy="title"></h1><p data-copy="lead"></p></section><aside id="demo-note" class="notice" hidden data-copy="demo"></aside><nav class="tabs" id="community-tabs"></nav><p id="community-status" role="status" aria-live="polite"></p><section id="auth-panel" class="panel" hidden><h2 data-copy="signIn"></h2><p data-copy="signInHelp"></p><form id="signin-form"><label><span data-copy="email"></span><input name="email" type="email" autocomplete="email" required maxlength="180" dir="ltr"></label><button data-copy="sendLink"></button></form><button id="confirm-login" hidden data-copy="confirmLogin"></button></section><section id="profile-panel" hidden><p id="profile-summary"></p><button id="signout" data-copy="signOut"></button></section><section id="submit-view"><form id="proposal-form" class="panel"><h2 data-copy="propose"></h2><label><span data-copy="kind"></span><select name="kind"></select></label><label><span data-copy="place"></span><input name="placeSearch" list="place-options" autocomplete="off" maxlength="220"><datalist id="place-options"></datalist></label><p class="hint" data-copy="unknownPlace"></p><label><span data-copy="placeName"></span><input name="placeName" maxlength="160"></label><label><span data-copy="locationHint"></span><input name="locationHint" maxlength="500"></label><label><span data-copy="proposalTitle"></span><input name="title" maxlength="160" required></label><label><span data-copy="story"></span><textarea name="text" rows="5" maxlength="4000"></textarea></label><section id="album-source" class="notice" hidden></section><label><span data-copy="files"></span><input name="files" type="file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/quicktime,video/webm" multiple></label><p class="hint" data-copy="fileHelp"></p><div id="file-previews" class="preview-grid"></div><label><span data-copy="credit"></span><input name="credit" maxlength="80" autocomplete="nickname"></label><label class="check"><input name="consent" type="checkbox" required><span data-copy="consent"></span></label><p class="hint" data-copy="privacy"></p><button class="primary" id="submit-proposal" data-copy="sendProposal"></button></form></section><section id="my-view" hidden></section><section id="public-view" hidden><h2 data-copy="public"></h2><p data-copy="publishedOnly"></p><div id="community-map" aria-label="Community map"></div><div id="public-items" class="cards"></div></section><section id="review-view" hidden><h2 data-copy="review"></h2><p data-copy="reviewHelp"></p><div id="review-items"></div></section></main><footer><a id="privacy-link" href="https://wroc-love.com/privacy.html" data-copy="privacyLink"></a></footer></body></html>
